import { useState } from "react";

interface UseControlledOpenProps {
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
}

interface UseControlledOpenResult {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  close: () => void;
}

export const useControlledOpen = ({
  open,
  onOpenChange,
}: UseControlledOpenProps): UseControlledOpenResult => {
  const [internalOpen, setInternalOpen] = useState(false);

  // Determine if the component is controlled or uncontrolled
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const setIsOpen = (newOpen: boolean) => {
    if (!isControlled) {
      setInternalOpen(newOpen);
    }
    if (onOpenChange) {
      onOpenChange(newOpen);
    }
  };

  const close = () => setIsOpen(false);

  return { close, isOpen, setIsOpen };
};

"use client";

import { CustomButton } from "@/registry/new-york/custom-button/CustomButton";
import type { SimpleDialogProps } from "@/registry/new-york/simple-dialog/SimpleDialogTypes";

type DialogActionsProps = Pick<
  SimpleDialogProps,
  "classNames" | "showCancel" | "onSubmit" | "submitText" | "cancelText"
> & {
  onCancel: () => void;
  onConfirm: () => void;
};

export const SimpleDialogActions = ({
  classNames,
  showCancel,
  onSubmit,
  submitText,
  cancelText,
  onCancel,
  onConfirm,
}: DialogActionsProps) => (
  <>
    {showCancel && (
      <CustomButton
        variant="outline"
        onClick={onCancel}
        className={classNames?.cancelButton}
      >
        {cancelText}
      </CustomButton>
    )}
    {onSubmit && (
      <CustomButton onClick={onConfirm} className={classNames?.submitButton}>
        {submitText}
      </CustomButton>
    )}
  </>
);

"use client";

import React from "react";

import {
  Dialog,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { useControlledOpen } from "@/registry/hooks/useControlledOpen";
import { BottomDrawer } from "@/registry/new-york/bottom-drawer/BottomDrawer";
import { useKitzeUI } from "@/registry/new-york/kitze-ui-context/KitzeUIContext";
import { SimpleDialogActions } from "@/registry/new-york/simple-dialog/SimpleDialogActions";
import {
  CustomDialogContent,
  sizeToMaxWidth,
  toDialogTriggerElement,
} from "@/registry/new-york/simple-dialog/SimpleDialogParts";
import type * as SimpleDialogTypesModule from "@/registry/new-york/simple-dialog/SimpleDialogTypes";

export type DialogClassNames = SimpleDialogTypesModule.DialogClassNames;
export type DialogMobileViewType = SimpleDialogTypesModule.DialogMobileViewType;
export type DialogSize = SimpleDialogTypesModule.DialogSize;
export type SimpleDialogProps = SimpleDialogTypesModule.SimpleDialogProps;
const EMPTY_CLASS_NAMES: NonNullable<SimpleDialogProps["classNames"]> = {};

export const SimpleDialog = ({
  trigger = "Open",
  title,
  children,
  open,
  onOpenChange,
  onOpenChangeComplete,
  size = "sm",
  classNames = EMPTY_CLASS_NAMES,
  mobileView = "keep",
  drawerTitle,
  showCloseButton = true,
  onCancel,
  onSubmit,
  showCancel = Boolean(onSubmit),
  submitText = "Submit",
  cancelText = "Cancel",
}: SimpleDialogProps) => {
  const { isMobile } = useKitzeUI();
  const { isOpen, setIsOpen, close } = useControlledOpen({
    onOpenChange,
    open,
  });
  const handleCancel = () => {
    close();
    if (onCancel) {
      onCancel();
    }
  };
  const handleSubmit = () => {
    if (onSubmit) {
      onSubmit();
    }
    close();
  };
  const actions = (
    <SimpleDialogActions
      classNames={classNames}
      showCancel={showCancel}
      onSubmit={onSubmit}
      submitText={submitText}
      cancelText={cancelText}
      onCancel={handleCancel}
      onConfirm={handleSubmit}
    />
  );
  const hasFooter = Boolean(onSubmit || showCancel);
  const triggerNode =
    open === undefined ? toDialogTriggerElement(trigger) : undefined;
  if (isMobile && mobileView === "bottom-drawer") {
    return (
      <BottomDrawer
        open={isOpen}
        onOpenChange={setIsOpen}
        onOpenChangeComplete={onOpenChangeComplete}
        trigger={triggerNode}
        title={drawerTitle || title}
        classNames={{
          childrenWrapper: classNames.drawerRoot,
          content: classNames.drawerContent,
          headerWrapper: classNames.drawerHeader,
        }}
      >
        <div className={classNames.body}>{children}</div>
        {hasFooter && (
          <div className={cn(classNames.drawerFooter, "pt-4")}>
            <div className={cn("flex justify-end gap-2", classNames.footer)}>
              {actions}
            </div>
          </div>
        )}
      </BottomDrawer>
    );
  }
  return (
    <Dialog
      open={isOpen}
      onOpenChange={setIsOpen}
      onOpenChangeComplete={onOpenChangeComplete}
    >
      {triggerNode ? (
        <DialogTrigger
          render={
            React.isValidElement(triggerNode) ? (
              triggerNode
            ) : (
              <button type="button">{triggerNode}</button>
            )
          }
        />
      ) : null}
      <CustomDialogContent
        className={cn(
          sizeToMaxWidth[size],
          classNames.root,
          classNames.content
        )}
        showCloseButton={showCloseButton}
      >
        {title ? (
          <DialogHeader className={classNames.header}>
            <DialogTitle className={classNames.title}>{title}</DialogTitle>
            <DialogDescription className="sr-only">
              {title} dialog
            </DialogDescription>
          </DialogHeader>
        ) : (
          <>
            <DialogTitle className="sr-only">Dialog</DialogTitle>
            <DialogDescription className="sr-only">
              Dialog content
            </DialogDescription>
          </>
        )}
        <div className={cn("text-sm", classNames.body)}>{children}</div>
        {hasFooter && (
          <DialogFooter className={classNames.footer}>{actions}</DialogFooter>
        )}
      </CustomDialogContent>
    </Dialog>
  );
};

import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { XIcon } from "lucide-react";
import React from "react";

import {
  DialogClose,
  DialogOverlay,
  DialogPortal,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { CustomButton } from "@/registry/new-york/custom-button/CustomButton";
import type { DialogSize } from "@/registry/new-york/simple-dialog/SimpleDialogTypes";

export const sizeToMaxWidth: Record<DialogSize, string> = {
  "2xl": "sm:max-w-[1024px]",
  "3xl": "sm:max-w-[1280px]",
  "4xl": "sm:max-w-[1536px]",
  "5xl": "sm:max-w-[1920px]",
  full: "sm:max-w-[100vw]",
  lg: "sm:max-w-[680px]",
  md: "sm:max-w-[550px]",
  sm: "sm:max-w-[425px]",
  xl: "sm:max-w-[800px]",
};
export const CustomDialogContent = ({
  className,
  children,
  showCloseButton = true,
  ...props
}: DialogPrimitive.Popup.Props & {
  showCloseButton?: boolean;
}) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Popup
      data-slot="dialog-content"
      className={cn(
        "bg-background fixed top-[50%] left-[50%] z-50 grid w-full max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%] gap-4 rounded-2xl border p-6 shadow-lg transition-[opacity,scale] duration-200 ease-out data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0 motion-reduce:transition-none sm:max-w-lg",
        className
      )}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogClose className="ring-offset-background focus:ring-ring hover:bg-accent text-muted-foreground absolute top-3 right-3 flex size-8 cursor-pointer items-center justify-center rounded-full opacity-70 transition-opacity hover:opacity-100 focus:ring-2 focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4">
          <XIcon />
          <span className="sr-only">Close</span>
        </DialogClose>
      )}
    </DialogPrimitive.Popup>
  </DialogPortal>
);
export const toDialogTriggerElement = (
  trigger: React.ReactNode
): React.ReactNode =>
  React.isValidElement(trigger) ? (
    trigger
  ) : (
    <CustomButton>{trigger}</CustomButton>
  );

import React from "react";

export type DialogMobileViewType = "keep" | "bottom-drawer";

export type DialogSize =
  | "sm"
  | "md"
  | "lg"
  | "xl"
  | "2xl"
  | "3xl"
  | "4xl"
  | "5xl"
  | "full";

export interface DialogClassNames {
  root?: string | undefined;
  content?: string | undefined;
  header?: string | undefined;
  title?: string | undefined;
  body?: string | undefined;
  footer?: string | undefined;
  submitButton?: string | undefined;
  cancelButton?: string | undefined;
  drawerRoot?: string | undefined;
  drawerContent?: string | undefined;
  drawerHeader?: string | undefined;
  drawerFooter?: string | undefined;
}

export interface SimpleDialogProps {
  trigger?: React.ReactNode | undefined;
  title?: string | undefined;
  children: React.ReactNode;
  open?: boolean | undefined;
  onOpenChangeComplete?: ((open: boolean) => void) | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  size?: DialogSize | undefined;
  classNames?: DialogClassNames | undefined;
  mobileView?: DialogMobileViewType | undefined;
  drawerTitle?: string | undefined;
  showCancel?: boolean | undefined;
  showCloseButton?: boolean | undefined;
  onCancel?: (() => void) | undefined;
  onSubmit?: (() => void) | undefined;
  submitText?: string | undefined;
  cancelText?: string | undefined;
}

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
